    let state = {
      profile: { ...defaultProfile },
      projects: [...defaultProjects],
      activeCategory: 'All',
      searchQuery: '',
      viewMode: 'grid',
      activeSkillTab: 'AI / ML & Data',
      likedIds: [],
      sentMessages: []
    };

    try {
      const saved = localStorage.getItem('altamash_portfolio_state_v2');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (parsed.profile) state.profile = { ...defaultProfile, ...parsed.profile };
        if (Array.isArray(parsed.projects)) state.projects = parsed.projects;
        if (Array.isArray(parsed.likedIds)) state.likedIds = parsed.likedIds;
        if (Array.isArray(parsed.sentMessages)) state.sentMessages = parsed.sentMessages;
      }
    } catch (e) {}

    function saveState() {
      try {
        localStorage.setItem('altamash_portfolio_state_v2', JSON.stringify({
          profile: state.profile,
          projects: state.projects,
          likedIds: state.likedIds,
          sentMessages: state.sentMessages
        }));
      } catch (e) {}
    }

    function showToast(msg) {
      const toast = document.getElementById('toast');
      document.getElementById('toastText').textContent = msg;
      toast.classList.remove('hidden');
      toast.classList.add('flex');
      clearTimeout(window._toastTimer);
      window._toastTimer = setTimeout(() => {
        toast.classList.add('hidden');
        toast.classList.remove('flex');
      }, 2600);
    }

    function copyText(text) {
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(() => showToast('Copied: ' + text)).catch(() => fallbackCopy(text));
      } else {
        fallbackCopy(text);
      }
    }

    function fallbackCopy(text) {
      const ta = document.createElement('textarea');
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); } catch (e) {}
      document.body.removeChild(ta);
      showToast('Copied: ' + text);
    }

    function renderProfile() {
      const p = state.profile;
      const initials = p.name.split(/\s+/).map(w => w[0]).join('').slice(0, 2).toUpperCase() || 'SA';
      document.getElementById('navMonogram').textContent = initials;
      document.getElementById('navName').textContent = p.name;
      document.getElementById('heroName').textContent = p.name;
      document.getElementById('cardName').textContent = p.name;
      document.getElementById('heroRole').textContent = p.role;
      document.getElementById('heroAvailability').textContent = p.availability;
      document.getElementById('heroBio').textContent = p.bio;
      document.getElementById('heroEmailText').textContent = p.email;
      document.getElementById('cardHandle').textContent = p.email;
      document.getElementById('contactEmailDisplay').textContent = p.email;
      document.getElementById('heroLocation').textContent = p.location;
      document.getElementById('contactLocationDisplay').textContent = p.location;
      document.getElementById('footerCopy').textContent = `© 2026 ${p.name}. All rights reserved.`;

      document.getElementById('resumeName').textContent = p.name;
      document.getElementById('resumeRole').textContent = p.role;
      document.getElementById('resumeMeta').textContent = `${p.location} • +91 8609287613 • ${p.email}`;
      document.getElementById('resumeBio').textContent = p.bio;

      document.getElementById('statProjects').textContent = state.projects.length;
      const totalLikes = state.projects.reduce((acc, pr) => acc + pr.likes, 0);
      document.getElementById('statLikes').textContent = totalLikes;
    }

    function renderProjects() {
      const container = document.getElementById('projectsGrid');
      const emptyState = document.getElementById('emptyProjectsState');
      const q = state.searchQuery.trim().toLowerCase();

      const filtered = state.projects.filter(proj => {
        const matchCat = state.activeCategory === 'All' || proj.category === state.activeCategory;
        const matchQuery = !q || proj.title.toLowerCase().includes(q) || proj.description.toLowerCase().includes(q) || proj.tags.some(t => t.toLowerCase().includes(q));
        return matchCat && matchQuery;
      });

      container.className = state.viewMode === 'grid'
        ? 'grid grid-cols-1 md:grid-cols-2 gap-6'
        : 'grid grid-cols-1 gap-4';

      if (filtered.length === 0) {
        container.innerHTML = '';
        emptyState.classList.remove('hidden');
        return;
      }
      emptyState.classList.add('hidden');

      container.innerHTML = filtered.map(proj => {
        const isLiked = state.likedIds.includes(proj.id);
        const mediaHtml = proj.image
          ? `<img src="${proj.image}" alt="${proj.title}" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />`
          : `<div class="w-full h-full bg-gradient-to-br from-indigo-600 via-violet-600 to-cyan-500 flex items-center justify-center p-6">
               <div class="text-white/90 text-center">
                 <div class="text-xs uppercase tracking-widest opacity-80 mb-1">${proj.category}</div>
                 <div class="text-xl font-bold">${proj.title}</div>
               </div>
             </div>`;

        const liveLinkChip = proj.liveUrl
          ? `<a href="${proj.liveUrl}" target="_blank" rel="noopener noreferrer" class="text-xs font-semibold text-emerald-600 dark:text-emerald-400 inline-flex items-center gap-1 hover:underline">
               <span>Live</span>
               <i data-lucide="external-link" class="w-3 h-3"></i>
             </a>`
          : '';

        return `
          <article data-proj-id="${proj.id}" class="project-card group rounded-3xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900/70 overflow-hidden hover:border-indigo-500/50 transition-all shadow-sm hover:shadow-xl ${state.viewMode === 'list' ? 'flex flex-col sm:flex-row' : ''}">
            <div class="${state.viewMode === 'list' ? 'sm:w-64 h-48 sm:h-auto shrink-0' : 'h-52'} overflow-hidden bg-zinc-900 relative cursor-pointer open-proj-trigger">
              ${mediaHtml}
              <span class="absolute top-3 left-3 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-black/60 text-white glass">${proj.category}</span>
            </div>
            <div class="p-6 flex-1 flex flex-col justify-between space-y-4">
              <div class="space-y-2">
                <div class="flex items-start justify-between gap-2">
                  <h3 class="text-lg font-bold group-hover:text-indigo-600 dark:group-hover:text-indigo-400 transition-colors cursor-pointer open-proj-trigger">${proj.title}</h3>
                  <button type="button" data-like-id="${proj.id}" class="like-btn inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-semibold border ${isLiked ? 'border-rose-500 bg-rose-500/10 text-rose-500' : 'border-zinc-200 dark:border-zinc-700 text-zinc-500 hover:text-rose-500'} transition-colors shrink-0">
                    <i data-lucide="heart" class="w-3.5 h-3.5 ${isLiked ? 'fill-current' : ''}"></i>
                    <span>${proj.likes}</span>
                  </button>
                </div>
                <p class="text-sm text-zinc-600 dark:text-zinc-400 line-clamp-2">${proj.description}</p>
              </div>
              <div class="flex items-center justify-between gap-3 pt-2">
                <div class="flex flex-wrap gap-1.5">
                  ${proj.tags.slice(0, 3).map(t => `<span class="px-2.5 py-0.5 rounded-md bg-zinc-100 dark:bg-zinc-800 text-[11px] font-medium text-zinc-700 dark:text-zinc-300">${t}</span>`).join('')}
                </div>
                <div class="flex items-center gap-3 shrink-0">
                  ${liveLinkChip}
                  <button type="button" class="open-proj-trigger text-xs font-semibold text-indigo-600 dark:text-indigo-400 inline-flex items-center gap-1 hover:underline">
                    <span>Details</span>
                    <i data-lucide="arrow-up-right" class="w-3.5 h-3.5"></i>
                  </button>
                </div>
              </div>
            </div>
          </article>
        `;
      }).join('');

      lucide.createIcons();
    }

    let skillsChartInstance = null;

    function renderSkills() {
      const items = skillsData[state.activeSkillTab] || [];
      document.getElementById('chartDomainBadge').textContent = state.activeSkillTab;
      document.getElementById('skillBarsContainer').innerHTML = items.map(s => `
        <div class="p-4 rounded-2xl border border-zinc-200 dark:border-zinc-800 bg-white dark:bg-zinc-900/60">
          <div class="flex justify-between text-xs font-semibold mb-2">
            <span>${s.name}</span>
            <span class="text-indigo-600 dark:text-indigo-400">${s.level}%</span>
          </div>
          <div class="h-2 rounded-full bg-zinc-200 dark:bg-zinc-800 overflow-hidden">
            <div class="h-full rounded-full bg-gradient-to-r from-indigo-500 to-cyan-400 transition-all duration-500" style="width: ${s.level}%"></div>
          </div>
        </div>
      `).join('');

      const ctx = document.getElementById('skillsChart').getContext('2d');
      const isDark = document.documentElement.classList.contains('dark');
      const gridColor = isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.08)';
      const labelColor = isDark ? '#a1a1aa' : '#52525b';

      if (skillsChartInstance) skillsChartInstance.destroy();
      skillsChartInstance = new Chart(ctx, {
        type: 'radar',
        data: {
          labels: items.map(i => i.name.split('&')[0].trim()),
          datasets: [{
            label: state.activeSkillTab,
            data: items.map(i => i.level),
            backgroundColor: 'rgba(99, 102, 241, 0.22)',
            borderColor: '#6366f1',
            pointBackgroundColor: '#22d3ee',
            borderWidth: 2
          }]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          scales: {
            r: {
              min: 0,
              max: 100,
              ticks: { display: false, stepSize: 25 },
              grid: { color: gridColor },
              angleLines: { color: gridColor },
              pointLabels: { color: labelColor, font: { size: 11, family: 'Inter' } }
            }
          },
          plugins: { legend: { display: false } }
        }
      });
    }

    function renderSentMessages() {
      const box = document.getElementById('savedMessagesBox');
      const list = document.getElementById('sentMessagesList');
      const badge = document.getElementById('sentCountBadge');
      if (state.sentMessages.length === 0) {
        box.classList.add('hidden');
        return;
      }
      box.classList.remove('hidden');
      badge.textContent = state.sentMessages.length;
      list.innerHTML = state.sentMessages.slice(-3).reverse().map(m =>
        `<li><strong>${m.type}</strong> from ${m.name} — "${m.message.slice(0, 48)}${m.message.length > 48 ? '...' : ''}"</li>`
      ).join('');
    }

    let activeModalProjId = null;
    function openProjectModal(id) {
      const proj = state.projects.find(p => p.id === id);
      if (!proj) return;
      activeModalProjId = id;
      const imgEl = document.getElementById('modalImg');
      if (proj.image) {
        imgEl.src = proj.image;
        imgEl.classList.remove('hidden');
      } else {
        imgEl.src = '';
        imgEl.classList.add('hidden');
      }
      const liveBtn = document.getElementById('modalLiveLink');
      if (proj.liveUrl) {
        liveBtn.href = proj.liveUrl;
        liveBtn.classList.remove('hidden');
      } else {
        liveBtn.classList.add('hidden');
      }
      document.getElementById('modalCategory').textContent = proj.category;
      document.getElementById('modalTitle').textContent = proj.title;
      document.getElementById('modalDesc').textContent = proj.description;
      document.getElementById('modalLikeCount').textContent = proj.likes;
      document.getElementById('modalHighlights').innerHTML = (proj.highlights || ['Interactive responsive implementation']).map(h => `<li>${h}</li>`).join('');
      document.getElementById('modalTags').innerHTML = proj.tags.map(t => `<span class="px-2.5 py-1 rounded-lg bg-zinc-100 dark:bg-zinc-800 text-xs font-medium">${t}</span>`).join('');
      document.getElementById('projectModal').classList.remove('hidden');
      lucide.createIcons();
    }

    function toggleLike(id) {
      const proj = state.projects.find(p => p.id === id);
      if (!proj) return;
      const idx = state.likedIds.indexOf(id);
      if (idx === -1) {
        state.likedIds.push(id);
        proj.likes += 1;
      } else {
        state.likedIds.splice(idx, 1);
        proj.likes = Math.max(0, proj.likes - 1);
      }
      saveState();
      renderProfile();
      renderProjects();
      if (activeModalProjId === id) {
        document.getElementById('modalLikeCount').textContent = proj.likes;
      }
    }

    // Typewriter effect
    const phrases = ['Python & Django', 'Scikit-learn Pipelines', 'Responsive UI/UX', 'Cloud Deployment'];
    let twIdx = 0, twChar = 0, twDeleting = false;
    function tickTypewriter() {
      const el = document.getElementById('typewriterText');
      if (!el) return;
      const word = phrases[twIdx];
      el.textContent = twDeleting ? word.slice(0, twChar--) : word.slice(0, twChar++);
      if (!twDeleting && twChar > word.length) {
        twDeleting = true;
        setTimeout(tickTypewriter, 1300);
        return;
      }
      if (twDeleting && twChar < 0) {
        twDeleting = false;
        twIdx = (twIdx + 1) % phrases.length;
        twChar = 0;
      }
      setTimeout(tickTypewriter, twDeleting ? 45 : 85);
    }
    tickTypewriter();

    // Event Listeners
    document.addEventListener('mousemove', (e) => {
      const sp = document.getElementById('spotlight');
      sp.style.setProperty('--x', e.clientX + 'px');
      sp.style.setProperty('--y', e.clientY + 'px');
    });

    document.getElementById('themeToggle').addEventListener('click', () => {
      document.documentElement.classList.toggle('dark');
      renderSkills();
    });

    document.getElementById('mobileMenuBtn').addEventListener('click', () => {
      document.getElementById('mobileMenu').classList.toggle('hidden');
    });
    document.querySelectorAll('.mobile-nav-link').forEach(el => {
      el.addEventListener('click', () => document.getElementById('mobileMenu').classList.add('hidden'));
    });

    document.getElementById('copyEmailBtn').addEventListener('click', () => copyText(state.profile.email));
    document.getElementById('contactCopyBtn').addEventListener('click', () => copyText(state.profile.email));
    document.getElementById('copyPhoneBtn').addEventListener('click', () => copyText('+91 8609287613'));

    document.getElementById('categoryFilters').addEventListener('click', (e) => {
      const btn = e.target.closest('.filter-btn');
      if (!btn) return;
      state.activeCategory = btn.dataset.cat;
      document.querySelectorAll('.filter-btn').forEach(b => {
        const active = b.dataset.cat === state.activeCategory;
        b.className = active
          ? 'filter-btn px-3.5 py-1.5 rounded-full text-xs font-semibold bg-indigo-600 text-white transition-colors'
          : 'filter-btn px-3.5 py-1.5 rounded-full text-xs font-semibold bg-zinc-200/70 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-300 hover:bg-zinc-300 dark:hover:bg-zinc-700 transition-colors';
      });
      renderProjects();
    });

    document.getElementById('projectSearch').addEventListener('input', (e) => {
      state.searchQuery = e.target.value;
      renderProjects();
    });

    document.getElementById('resetFiltersBtn').addEventListener('click', () => {
      state.activeCategory = 'All';
      state.searchQuery = '';
      document.getElementById('projectSearch').value = '';
      document.querySelectorAll('.filter-btn').forEach(b => {
        const active = b.dataset.cat === 'All';
        b.className = active
          ? 'filter-btn px-3.5 py-1.5 rounded-full text-xs font-semibold bg-indigo-600 text-white transition-colors'
          : 'filter-btn px-3.5 py-1.5 rounded-full text-xs font-semibold bg-zinc-200/70 dark:bg-zinc-800 text-zinc-700 dark:text-zinc-300 hover:bg-zinc-300 dark:hover:bg-zinc-700 transition-colors';
      });
      renderProjects();
    });

    document.getElementById('toggleViewBtn').addEventListener('click', () => {
      state.viewMode = state.viewMode === 'grid' ? 'list' : 'grid';
      renderProjects();
    });

    document.getElementById('projectsGrid').addEventListener('click', (e) => {
      const likeBtn = e.target.closest('.like-btn');
      if (likeBtn) {
        toggleLike(likeBtn.dataset.likeId);
        return;
      }
      const trigger = e.target.closest('.open-proj-trigger');
      if (trigger) {
        const card = trigger.closest('.project-card');
        if (card) openProjectModal(card.dataset.projId);
      }
    });

    document.getElementById('closeProjectModal').addEventListener('click', () => {
      document.getElementById('projectModal').classList.add('hidden');
    });
    document.getElementById('modalLikeBtn').addEventListener('click', () => {
      if (activeModalProjId) toggleLike(activeModalProjId);
    });

    // Add Project Modal
    document.getElementById('openAddProjectBtn').addEventListener('click', () => {
      document.getElementById('addProjectModal').classList.remove('hidden');
    });
    document.getElementById('closeAddProjectModal').addEventListener('click', () => {
      document.getElementById('addProjectModal').classList.add('hidden');
    });
    document.getElementById('cancelAddProject').addEventListener('click', () => {
      document.getElementById('addProjectModal').classList.add('hidden');
    });
    document.getElementById('addProjectForm').addEventListener('submit', (e) => {
      e.preventDefault();
      const title = document.getElementById('newProjTitle').value.trim();
      const category = document.getElementById('newProjCat').value;
      const tags = document.getElementById('newProjTags').value.split(',').map(s => s.trim()).filter(Boolean);
      const liveUrl = document.getElementById('newProjUrl').value.trim();
      const description = document.getElementById('newProjDesc').value.trim();
      if (!title || !description) return;
      state.projects.unshift({
        id: 'proj-' + Date.now(),
        title,
        category,
        image: '',
        liveUrl,
        description,
        tags: tags.length ? tags : ['Web'],
        highlights: ['Added dynamically via interactive portfolio builder'],
        likes: 1
      });
      saveState();
      renderProfile();
      renderProjects();
      e.target.reset();
      document.getElementById('addProjectModal').classList.add('hidden');
      showToast('Project published!');
    });

    // Skills Tabs
    document.getElementById('skillTabs').addEventListener('click', (e) => {
      const btn = e.target.closest('.skill-tab-btn');
      if (!btn) return;
      state.activeSkillTab = btn.dataset.skillTab;
      document.querySelectorAll('.skill-tab-btn').forEach(b => {
        const active = b.dataset.skillTab === state.activeSkillTab;
        b.className = active
          ? 'skill-tab-btn px-3.5 py-2 rounded-lg text-xs font-semibold bg-white dark:bg-zinc-800 shadow-sm transition-all'
          : 'skill-tab-btn px-3.5 py-2 rounded-lg text-xs font-semibold text-zinc-600 dark:text-zinc-400 transition-all';
      });
      renderSkills();
    });

    // Journey Tabs
    document.getElementById('journeyTabs').addEventListener('click', (e) => {
      const btn = e.target.closest('.journey-tab-btn');
      if (!btn) return;
      const target = btn.dataset.journey;
      document.querySelectorAll('.journey-tab-btn').forEach(b => {
        const active = b.dataset.journey === target;
        b.className = active
          ? 'journey-tab-btn px-3.5 py-1.5 rounded-lg text-xs font-semibold bg-white dark:bg-zinc-800 shadow-sm transition-all'
          : 'journey-tab-btn px-3.5 py-1.5 rounded-lg text-xs font-semibold text-zinc-600 dark:text-zinc-400 transition-all';
      });
      document.querySelectorAll('.journey-panel').forEach(p => {
        p.classList.toggle('hidden', p.id !== 'panel-' + target);
      });
    });

    // Contact Form
    document.getElementById('contactForm').addEventListener('submit', (e) => {
      e.preventDefault();
      const name = document.getElementById('senderName').value.trim();
      const email = document.getElementById('senderEmail').value.trim();
      const type = document.getElementById('projectType').value;
      const message = document.getElementById('senderMessage').value.trim();
      if (!name || !email || !message) return;
      state.sentMessages.push({ name, email, type, message, date: new Date().toISOString() });
      saveState();
      renderSentMessages();
      e.target.reset();
      showToast('Inquiry recorded! Thank you, ' + name);
    });

    // Resume Modal & Download
    document.getElementById('openResumeBtn').addEventListener('click', () => {
      document.getElementById('resumeModal').classList.remove('hidden');
    });
    document.getElementById('closeResumeModal').addEventListener('click', () => {
      document.getElementById('resumeModal').classList.add('hidden');
    });
    document.getElementById('downloadResumeBtn').addEventListener('click', () => {
      const p = state.profile;
      const content = `${p.name}\n${p.role}\n${p.location} | +91 8609287613 | ${p.email}\nLinkedIn: linkedin.com/in/sk-altamash-ali-a5078a34b | GitHub: github.com/Altamash-022\n\nPROFESSIONAL SUMMARY\n${p.bio}\n\nEDUCATION\n- BCA, The Neotia University, Sarisha (Aug 2023 - Present)\n- Class XII (WBCHSE), Kishore Nagar Sachindra Siksha Sadan, Contai (2023, 74.00%)\n- Class X (WBBSE), Kishore Nagar Sachindra Siksha Sadan, Contai (2021, 76.43%)\n\nKEY PROJECTS\n` +
        state.projects.map(pr => `- ${pr.title} (${pr.category}): ${pr.description}${pr.liveUrl ? ' [' + pr.liveUrl + ']' : ''}`).join('\n');
      const blob = new Blob([content], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${p.name.replace(/\s+/g, '_')}_Resume.txt`;
      a.click();
      URL.revokeObjectURL(url);
      showToast('Resume downloaded');
    });

    // Customize Drawer
    document.getElementById('customizeBtn').addEventListener('click', () => {
      document.getElementById('editName').value = state.profile.name;
      document.getElementById('editRole').value = state.profile.role;
      document.getElementById('editAvailability').value = state.profile.availability;
      document.getElementById('editBio').value = state.profile.bio;
      document.getElementById('editEmail').value = state.profile.email;
      document.getElementById('customizeDrawer').classList.remove('hidden');
    });
    document.getElementById('closeCustomize').addEventListener('click', () => {
      document.getElementById('customizeDrawer').classList.add('hidden');
    });
    document.getElementById('saveCustomBtn').addEventListener('click', () => {
      state.profile.name = document.getElementById('editName').value.trim() || defaultProfile.name;
      state.profile.role = document.getElementById('editRole').value.trim() || defaultProfile.role;
      state.profile.availability = document.getElementById('editAvailability').value.trim() || defaultProfile.availability;
      state.profile.bio = document.getElementById('editBio').value.trim() || defaultProfile.bio;
      state.profile.email = document.getElementById('editEmail').value.trim() || defaultProfile.email;
      saveState();
      renderProfile();
      document.getElementById('customizeDrawer').classList.add('hidden');
      showToast('Profile updated');
    });
    document.getElementById('resetCustomBtn').addEventListener('click', () => {
      state.profile = { ...defaultProfile };
      saveState();
      renderProfile();
      document.getElementById('customizeDrawer').classList.add('hidden');
      showToast('Profile reset to defaults');
    });

    // Command Palette
    const commands = [
      { label: 'Go to Projects', action: () => location.hash = '#projects' },
      { label: 'Go to Skills & Chart', action: () => location.hash = '#skills' },
      { label: 'Go to Certificates', action: () => location.hash = '#certificates' },
      { label: 'Go to Experience & Education', action: () => location.hash = '#journey' },
      { label: 'Go to Contact Form', action: () => location.hash = '#contact' },
      { label: 'Toggle Light / Dark Theme', action: () => document.getElementById('themeToggle').click() },
      { label: 'Open Interactive Resume', action: () => document.getElementById('openResumeBtn').click() },
      { label: 'Customize Portfolio Profile', action: () => document.getElementById('customizeBtn').click() },
      { label: 'Copy Email Address', action: () => copyText(state.profile.email) }
    ];

    function renderCommands(filter = '') {
      const list = document.getElementById('cmdList');
      const q = filter.toLowerCase();
      const matched = commands.filter(c => c.label.toLowerCase().includes(q));
      list.innerHTML = matched.map(c =>
        `<button type="button" data-cmd-idx="${commands.indexOf(c)}" class="cmd-item w-full text-left px-3 py-2 rounded-xl hover:bg-indigo-500/10 hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors">${c.label}</button>`
      ).join('') || '<div class="px-3 py-4 text-xs text-zinc-500 text-center">No matching commands</div>';
    }

    document.getElementById('cmdBtn').addEventListener('click', () => {
      renderCommands();
      document.getElementById('cmdModal').classList.remove('hidden');
      document.getElementById('cmdInput').focus();
    });
    document.getElementById('closeCmdModal').addEventListener('click', () => {
      document.getElementById('cmdModal').classList.add('hidden');
    });
    document.getElementById('cmdInput').addEventListener('input', (e) => renderCommands(e.target.value));
    document.getElementById('cmdList').addEventListener('click', (e) => {
      const btn = e.target.closest('.cmd-item');
      if (!btn) return;
      const idx = Number(btn.dataset.cmdIdx);
      document.getElementById('cmdModal').classList.add('hidden');
      commands[idx].action();
    });

    document.querySelectorAll('.certificate-card').forEach(card => {
      card.addEventListener('click', () => {
        const modal = document.getElementById('certificateModal');
        const image = document.getElementById('certificateModalImage');
        document.getElementById('certificateModalTitle').textContent = card.dataset.title;
        image.src = card.dataset.certificate;
        image.alt = card.dataset.title;
        modal.classList.remove('hidden');
        document.body.classList.add('overflow-hidden');
      });
    });

    document.getElementById('closeCertificateModal').addEventListener('click', () => {
      document.getElementById('certificateModal').classList.add('hidden');
      document.body.classList.remove('overflow-hidden');
    });
    document.getElementById('certificateModal').addEventListener('click', (e) => {
      if (e.target.id === 'certificateModal') {
        e.currentTarget.classList.add('hidden');
        document.body.classList.remove('overflow-hidden');
      }
    });

    document.addEventListener('keydown', (e) => {
      if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        renderCommands();
        document.getElementById('cmdModal').classList.remove('hidden');
        document.getElementById('cmdInput').focus();
      } else if (e.key === 'Escape') {
        ['projectModal', 'addProjectModal', 'resumeModal', 'customizeDrawer', 'cmdModal', 'certificateModal'].forEach(id => {
          document.getElementById(id).classList.add('hidden');
        });
        document.body.classList.remove('overflow-hidden');
      }
    });

    document.getElementById('scrollTopBtn').addEventListener('click', () => {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    });

    function updateClock() {
      const now = new Date();
      document.getElementById('liveClock').textContent = now.toLocaleTimeString('en-IN', { hour12: true });
    }
    setInterval(updateClock, 1000);
    updateClock();

    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) entry.target.classList.add('visible');
      });
    }, { threshold: 0.08 });
    document.querySelectorAll('.reveal').forEach(el => observer.observe(el));

    window.addEventListener('DOMContentLoaded', () => {
      renderProfile();
      renderProjects();
      renderSkills();
      renderSentMessages();
      lucide.createIcons();
    });
